-- public.vessel_says(p placed)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.vessel_says(p placed)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select placed_name(p) || ': Quality ' || to_char(p.ql, 'FM990.00') || ', '
      || round(placed_litres(p))::bigint || ' of ' || round(liquid_capacity(p))::bigint || ' litres. '
      || case when placed_litres(p) <= 0 or placed_liquid(p) is null then 'Empty.'
              when placed_dye(p) is not null then 'Holds: ' || dye_says(placed_dye(p), placed_litres(p))
              else 'Holds: ' || round(placed_litres(p))::bigint || ' litres of '
                   || (select name from liquid_def where id = placed_liquid(p)) || '.' end
      -- And a wine kept in it: how long and where, and what it has gained (`wineAgeSays`).
      || wine_age_says(p, extract(epoch from now())::double precision)
      -- And a brewer's spring (`brewSpringSays`).
      || private.brew_spring_says(p)
$function$
